const V43_LANGUAGES=['en','uk','ja','fr','it','id','ar','ko','sv','pt','nl','th','km','fil'];
for(const [source,row] of Object.entries(V43_ROWS)){
 if(row.length!==V43_LANGUAGES.length)throw new Error('Incomplete officer translation: '+source);
 V43_LANGUAGES.forEach((lang,index)=>{TRANSLATION_ROWS[lang][source]=row[index]});
}
// These complete translations already existed in the dynamic and fragment tables.
