export const OFFICER_LANGUAGES=Object.freeze(['de','en','uk','ja','fr','it','id','ar','ko','sv','pt','nl','th','km','fil']);
export function officerLanguage(documentRef=globalThis.document){
 const current=String(documentRef?.documentElement?.lang||'de').toLowerCase();
 return OFFICER_LANGUAGES.includes(current)?current:'de';
}
export function officerLocale(documentRef=globalThis.document){
 return LOCALES[officerLanguage(documentRef)]||'de-DE';
}
export function translateOfficerText(source,lang='de'){
 if(lang==='de'||!OFFICER_TEXT[lang]||typeof source!=='string')return source;
 const trimmed=source.trim();
 if(!trimmed)return source;
 // Capture-date summary: translate only fixed UI labels and approved fragments.
 const captured=/^Stärke (\d{4}-\d{2}-\d{2}) · VS ([0-9W-]+) · (.+)$/u.exec(trimmed);
 if(captured){
  const power=OFFICER_TEXT[lang]['Stärke'];
  const detail=translateOfficerFragments(captured[3],lang);
  if(power&&power!=='Stärke'&&detail!==captured[3]){
   return (source.match(/^\s*/u)?.[0]||'')+power+' '+captured[1]+' · VS '+captured[2]+' · '+detail+(source.match(/\s*$/u)?.[0]||'');
  }
 }
 let translated=OFFICER_TEXT[lang][trimmed];
 let dynamicMatched=false;
 if(!translated){
  const dynamic=translateOfficerDynamicText(trimmed,lang);
  if(dynamic!==trimmed){translated=dynamic;dynamicMatched=true;}
 }
 // Translate only numeric UI counters built from known static labels.
 // Never guess player names, arbitrary server values or user-entered text.
 if(!translated){
  const counted=/^([0-9][0-9., ]*)\s+(.+)$/u.exec(trimmed);
  if(counted && /^(Spieler|Mitglieder|Fahrten|Gewinne|Tage|bestätigte Tage|offene Prüffälle|passende Einträge)$/u.test(counted[2])){
   const phrase=lang==='en'&&counted[2]==='Spieler'?'Players':OFFICER_TEXT[lang][counted[2]];
   if(phrase)translated=counted[1]+' '+phrase;
  }
  const withCount=!translated && /^(.+?)\s+\(([0-9., ]+)\)$/u.exec(trimmed);
  if(withCount && OFFICER_TEXT[lang][withCount[1]]){
   translated=OFFICER_TEXT[lang][withCount[1]]+' ('+withCount[2]+')';
  }
 }
 if(!translated){const fragment=translateOfficerFragments(trimmed,lang);if(fragment!==trimmed)translated=fragment;}
 // A dynamic sentence can contain more than one authored UI phrase.
 // Translate remaining approved source fragments after the first match too.
 // Dynamic template captures may contain private member names. Never rewrite those captures as UI fragments.
 if(typeof translated==='string'&&translated&&!dynamicMatched)translated=translateOfficerFragments(translated,lang);
 if(typeof translated!=='string'||!translated||translated===trimmed)return source;
 const start=source.match(/^\s*/u)?.[0]||'';
 const end=source.match(/\s*$/u)?.[0]||'';
 return start+translated+end;
}
const textNodes=(root)=>root.ownerDocument.createTreeWalker(root,4);
const SKIP_PARENTS=new Set(['SCRIPT','STYLE','TEXTAREA','OPTIONHIDDEN','CODE','PRE']);
const PRIVATE_NAME_NODES='.native-rank-members [data-native-member] strong,.native-profile-identity h3,.native-train-candidates b,.native-review-people [data-native-review-pick] strong,[data-registry-edit] strong,.native-train-unlinked-group strong';
function isStaticNode(node){
 const parent=node.parentElement;
 if(!parent||SKIP_PARENTS.has(parent.tagName)||parent.closest('[contenteditable="true"],[data-native-no-translate]'))return false;
 if(parent.matches(PRIVATE_NAME_NODES))return false;
 if(parent.matches('.native-train-item > div:first-child > strong')&&node.nodeValue!=='Noch kein Fahrer eingetragen')return false;
 if(parent.tagName==='OPTION'&&parent.value&&/^(?:member|officer|driver|substitute)_id$/u.test(parent.parentElement?.name||''))return false;
 return true;
}
export function localizeOfficerTree(root,lang=officerLanguage(root?.ownerDocument)){
 if(!root||lang==='de'||!OFFICER_TEXT[lang])return 0;
 let count=0;
 const walker=textNodes(root),nodes=[];
 while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){
  if(!isStaticNode(node))continue;
  const next=translateOfficerText(node.nodeValue,lang);
  if(next!==node.nodeValue){node.nodeValue=next;count++}
 }
 for(const element of root.querySelectorAll('[placeholder],[title],[aria-label],[alt]')){
  if(element.closest('[data-native-no-translate]'))continue;
  for(const field of ['placeholder','title','aria-label','alt']){
   if(!element.hasAttribute(field))continue;
   const before=element.getAttribute(field);
   const after=translateOfficerText(before,lang);
   if(after!==before){element.setAttribute(field,after);count++}
  }
 }
 return count;
}
